//
// Forward launchers of the Inkling attention parts on the FlashAttention-2 fork (namespace inkling_flash; the
// headers next to this file are generated by make_fork.py from upstream/ v2.8.3). Two instantiations, hdim 128 bf16,
// FA2's own sm_120 tile choice for hdim 128 (128 x 64, 4 warps; run_mha_fwd_hdim128, non-sm8x branch).

#define FLASH_NAMESPACE inkling_flash

#include <cutlass/numeric_types.h>

#include <cmath>
#include <cstring>
#include <stdexcept>
#include <string>

#include "flash.h"
#include "flash_fwd_kernel.h"
#include "kernel_traits.h"
#include "kernels/inkling/flash_rel/inkling_attention.h"

// Named, not anonymous: nvcc host stubs of kernels in an anonymous namespace become ambiguous next to the
// global `using namespace cute;` of the FA2 headers.
namespace inkling_flash_fwd_detail {

using Traits = inkling_flash::Flash_fwd_kernel_traits<128, 128, 64, 4, false, false, cutlass::bfloat16_t>;

template <bool Is_causal, bool Is_local, bool Has_rel>
__global__ void __launch_bounds__(Traits::kNThreads) inkling_fwd_kernel(__grid_constant__ const inkling_flash::Flash_fwd_params params) {
#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 800
    static_assert(!(Is_causal && Is_local));
    // grid: (m_block, segment, head) as FA2's compute_attn
    inkling_flash::compute_attn_1rowblock<Traits, /*Is_dropout=*/false, Is_causal, Is_local, Has_rel,
                                          /*Is_even_MN=*/false, /*Is_even_K=*/true, /*Is_softcap=*/false,
                                          /*Return_softmax=*/false>(params, blockIdx.y, blockIdx.z, blockIdx.x);
#endif
}

__global__ void far_seqused_kernel(int* seqused, const int* cu_k, int num_segs, int window) {
    const int s = blockIdx.x * blockDim.x + threadIdx.x;
    if (s < num_segs) seqused[s] = max(cu_k[s + 1] - cu_k[s] - window, 0);
}

void fill_params(inkling_flash::Flash_fwd_params& p, const inkling::AttnPartArgs& a, bool far) {
    std::memset(&p, 0, sizeof(p));
    constexpr int D = 128;
    p.q_ptr = const_cast<nv_bfloat16*>(a.q);
    p.k_ptr = const_cast<nv_bfloat16*>(a.k);
    p.v_ptr = const_cast<nv_bfloat16*>(a.v);
    p.o_ptr = a.out;
    p.q_row_stride = a.q_row_stride ? a.q_row_stride : static_cast<long>(a.Hq) * D;
    p.k_row_stride = a.k_row_stride ? a.k_row_stride : static_cast<long>(a.Hkv) * D;
    p.v_row_stride = a.v_row_stride ? a.v_row_stride : static_cast<long>(a.Hkv) * D;
    p.q_head_stride = p.k_head_stride = p.v_head_stride = D;
    p.o_row_stride = static_cast<long>(a.Hq) * D;
    p.o_head_stride = D;
    p.h = a.Hq;
    p.h_k = a.Hkv;
    p.h_h_k_ratio = a.Hq / a.Hkv;
    p.b = a.num_segs;
    p.seqlen_q = a.max_q;
    p.seqlen_k = a.max_k;
    p.d = D;
    p.d_rounded = D;
    p.seqlen_q_rounded = (a.max_q + 127) / 128 * 128;
    p.seqlen_k_rounded = (a.max_k + 127) / 128 * 128;
    p.total_q = a.total_q;
    p.scale_softmax = a.scale;
    p.scale_softmax_log2 = a.scale * static_cast<float>(M_LOG2E);
    p.cu_seqlens_q = const_cast<int*>(a.cu_q);
    p.cu_seqlens_k = const_cast<int*>(a.cu_k);
    p.is_seqlens_k_cumulative = true;
    p.seqused_k = far ? a.seqused_k : nullptr;
    p.softmax_lse_ptr = a.lse;
    p.is_bf16 = true;
    p.is_causal = far;
    p.p_dropout = 1.0f;
    p.rp_dropout = 1.0f;
    p.scale_softmax_rp_dropout = a.scale;
    p.p_dropout_in_uint8_t = 255;
    p.window_size_left = far ? -1 : a.window - 1;
    p.window_size_right = 0;
    p.softcap = 0.0f;
    p.unpadded_lse = true;
    p.num_splits = 0;
    p.rel_ptr = far ? nullptr : const_cast<nv_bfloat16*>(a.rel);
    p.rel_row_stride = static_cast<long>(a.Hq) * a.rel_extent;
    p.rel_extent = a.rel_extent;
}

template <bool Is_causal, bool Is_local, bool Has_rel>
void launch(const inkling_flash::Flash_fwd_params& p, int max_q, cudaStream_t stream) {
    auto kernel = &inkling_fwd_kernel<Is_causal, Is_local, Has_rel>;
    constexpr int smem = Traits::kSmemSize;
    if (smem >= 48 * 1024) {
        const cudaError_t e = cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, smem);
        if (e != cudaSuccess) throw std::runtime_error(std::string("inkling attention fwd smem: ") + cudaGetErrorString(e));
    }
    const dim3 grid((max_q + Traits::kBlockM - 1) / Traits::kBlockM, p.b, p.h);
    kernel<<<grid, Traits::kNThreads, smem, stream>>>(p);
    const cudaError_t e = cudaGetLastError();
    if (e != cudaSuccess) throw std::runtime_error(std::string("inkling attention fwd: ") + cudaGetErrorString(e));
}

void check(const inkling::AttnPartArgs& a) {
    if (a.Hkv <= 0 || a.Hq % a.Hkv) throw std::invalid_argument("inkling attention: Hq % Hkv");
    if (!a.q || !a.k || !a.v || !a.cu_q || !a.cu_k || !a.out || !a.lse) throw std::invalid_argument("inkling attention: null");
    if (a.window <= 0) throw std::invalid_argument("inkling attention: window");
}

}  // namespace inkling_flash_fwd_detail

namespace inkling {

using namespace inkling_flash_fwd_detail;

void attention_near_fwd(const AttnPartArgs& a, cudaStream_t stream) {
    check(a);
    if (!a.rel || a.rel_extent < a.window) throw std::invalid_argument("inkling attention near: rel / extent");
    if (a.total_q == 0) return;
    inkling_flash::Flash_fwd_params p;
    fill_params(p, a, /*far=*/false);
    launch</*Is_causal=*/false, /*Is_local=*/true, /*Has_rel=*/true>(p, a.max_q, stream);
}

void attention_far_fwd(const AttnPartArgs& a, cudaStream_t stream) {
    check(a);
    if (!a.seqused_k) throw std::invalid_argument("inkling attention far: seqused_k scratch");
    if (a.total_q == 0) return;
    far_seqused_kernel<<<(a.num_segs + 127) / 128, 128, 0, stream>>>(a.seqused_k, a.cu_k, a.num_segs, a.window);
    inkling_flash::Flash_fwd_params p;
    fill_params(p, a, /*far=*/true);
    launch</*Is_causal=*/true, /*Is_local=*/false, /*Has_rel=*/false>(p, a.max_q, stream);
}

}  // namespace inkling
